-- English localization for Trentrouls, the Ultimate Possessor.

INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES
('TXT_KEY_TRAIT_ULTIMATE_TWO_POSSESSIONS_SHORT', 'Two Possessions for the Price of One'),
('TXT_KEY_TRAIT_ULTIMATE_TWO_POSSESSIONS_HELP', 'May temporarily possess several enemy or Barbarian units near your military units and cities. Maximum targets increase from 1 in the Ancient Era to 8 in the Information Era. Possessing more units creates a longer cooldown.'),

('TXT_KEY_LEADER_ULTIMATE_TRENTROULS', 'Trentrouls'),
('TXT_KEY_LEADER_ULTIMATE_TRENTROULS_PEDIA', 'Trentrouls, Ultimate Possessor of Una Court, does not ask why he should have one army when the world already contains so many perfectly good ones.'),
('TXT_KEY_CIVILOPEDIA_LEADERS_ULTIMATE_TRENTROULS', 'Trentrouls, the Ultimate Possessor'),

('TXT_KEY_CIV_ULTIMATE_POSSESSION_DESC', 'Trentrouls - Ultimate Possession'),
('TXT_KEY_CIV_ULTIMATE_POSSESSION_SHORT_DESC', 'Ultimate Possession'),
('TXT_KEY_CIV_ULTIMATE_POSSESSION_ADJECTIVE', 'Ultimate'),
('TXT_KEY_CIV_ULTIMATE_POSSESSION_PEDIA', 'From Una Court, Trentrouls reaches across the ages and takes what is his. The Ultimate Possession turns nearby enemy armies into temporary instruments of the Court, supported by loyal Golden Retrievers and the institutions of Centrelink and 3 Una Court.'),
('TXT_KEY_CIV5_ULTIMATE_POSSESSION', 'Ultimate Possession'),
('TXT_KEY_CIV_ULTIMATE_POSSESSION_STRATEGY', 'Ultimate Possession rewards careful staging. Place military units and cities near valuable enemy formations, then use the Una Court command panel to seize up to your current Era capacity at once. A larger group creates a longer cooldown, so take only the bodies you can exploit. Golden Retrievers keep a battle group moving and fighting, while Centrelink and 3 Una Court stabilize and enrich a broad empire.'),
('TXT_KEY_CIV5_DOM_ULTIMATE_POSSESSION_TEXT', 'Trentrouls, Ultimate Possessor of Una Court, the world arrives at your throne already full of armies waiting to be borrowed. Your reach grows with every age, from a single uncertain vessel to whole formations bent to your will. Let Golden Retrievers guard your soldiers, let Centrelink steady your cities, and raise 3 Una Court as the heart of your dominion. Why have one army, when you can have yours too?'),

('TXT_KEY_UNIT_ULTIMATE_GOLDEN_RETRIEVER', 'Golden Retriever'),
('TXT_KEY_UNIT_ULTIMATE_GOLDEN_RETRIEVER_HELP', 'Replaces the Scout. Costs more [ICON_PRODUCTION] Production and maintenance, but has +1 [ICON_MOVES] Movement. Good Boy grants adjacent friendly units +10% [ICON_STRENGTH] Combat Strength and +5 HP healing per turn. This aura does not stack.'),
('TXT_KEY_UNIT_ULTIMATE_GOLDEN_RETRIEVER_STRATEGY', 'The Golden Retriever is a fast reconnaissance and support unit. Keep it adjacent to a concentrated battle group to improve both combat strength and recovery. Multiple Golden Retrievers do not stack Good Boy.'),
('TXT_KEY_UNIT_ULTIMATE_GOLDEN_RETRIEVER_PEDIA', 'Una Court has always understood that an army needs loyalty as much as steel. The Golden Retriever ranges ahead like a Scout, then stays close to the soldiers who need the encouragement of a very good boy.'),

('TXT_KEY_PROMOTION_ULTIMATE_GOOD_BOY', 'Good Boy'),
('TXT_KEY_PROMOTION_ULTIMATE_GOOD_BOY_HELP', 'Adjacent friendly units receive +10% [ICON_STRENGTH] Combat Strength and +5 HP healing per turn. This bonus does not stack.'),
('TXT_KEY_PROMOTION_ULTIMATE_GOOD_BOY_AURA', 'Good Boy'),
('TXT_KEY_PROMOTION_ULTIMATE_GOOD_BOY_AURA_HELP', '+10% [ICON_STRENGTH] Combat Strength and +5 HP healing per turn from an adjacent Golden Retriever. This bonus does not stack.'),
('TXT_KEY_PROMOTION_ULTIMATE_POSSESSED', 'Mass Possession'),
('TXT_KEY_PROMOTION_ULTIMATE_POSSESSED_HELP', 'Temporarily controlled by Trentrouls. This unit cannot be deleted, gifted, or upgraded. If it survives, it returns to its original owner when possession ends.'),

('TXT_KEY_BUILDING_ULTIMATE_3_UNA_COURT', '3 Una Court'),
('TXT_KEY_BUILDING_ULTIMATE_3_UNA_COURT_HELP', 'Unique National Wonder. Provides +1 [ICON_HAPPINESS_1] Happiness in every City and +5% [ICON_GOLD] Gold in every City. Unemployed Citizens in every City produce +1 [ICON_CULTURE] Culture.'),
('TXT_KEY_BUILDING_ULTIMATE_3_UNA_COURT_STRATEGY', '3 Una Court is a powerful empire-wide National Wonder. Build it when expansion has created enough cities and unemployed population to benefit from its Happiness, Gold, and Culture.'),
('TXT_KEY_BUILDING_ULTIMATE_3_UNA_COURT_PEDIA', 'The grand house at 3 Una Court is less a residence than the fixed point around which a court of borrowed minds revolves. Its gold-and-purple halls promise prosperity, composure, and something useful for every otherwise idle citizen to do.'),

('TXT_KEY_CITY_NAME_ULTIMATE_UNA_COURT', 'Una Court'),
('TXT_KEY_CITY_NAME_ULTIMATE_PURPLE_COURT', 'Purple Court'),
('TXT_KEY_CITY_NAME_ULTIMATE_MANY_BODIES', 'Many Bodies'),
('TXT_KEY_CITY_NAME_ULTIMATE_GOLDEN_HALL', 'Golden Hall'),
('TXT_KEY_CITY_NAME_ULTIMATE_CENTRELINK', 'Centrelink'),
('TXT_KEY_CITY_NAME_ULTIMATE_GOOD_BOY', 'Good Boy Crossing'),
('TXT_KEY_CITY_NAME_ULTIMATE_THRONE', 'Possessor''s Throne'),
('TXT_KEY_CITY_NAME_ULTIMATE_LAST_WILL', 'The Last Will'),

('TXT_KEY_SPY_NAME_ULTIMATE_VESSEL', 'The Vessel'),
('TXT_KEY_SPY_NAME_ULTIMATE_HANDLER', 'The Handler'),
('TXT_KEY_SPY_NAME_ULTIMATE_GOOD_BOY', 'Good Boy');
